<template><div><Input :value="display" :disabled="disabled" :placeholder="placeholder||'请输入金额（元）'" @input="input"><span slot="append">{{suffix}}</span></Input><p v-if="error" class="ui-error" role="alert">{{error}}</p></div></template>
<script>import {decimal,minor} from '../display.cjs';export default {props:{value:Number,disabled:Boolean,placeholder:String,suffix:{type:String,default:'元'},maximum:{type:Number,default:99999999}},data:()=>({draft:null,error:''}),computed:{display(){return this.draft!==null?this.draft:this.value==null?'':decimal(this.value);}},watch:{value(value){if(value===null||value===undefined)this.draft=null;}},methods:{input(value){this.draft=value;this.error='';if(value===''){this.$emit('input',null);this.$emit('valid',false);return;}try{const result=minor(value,2,this.maximum);this.$emit('input',result);this.$emit('valid',true);}catch(e){this.error=e.message;this.$emit('input',null);this.$emit('valid',false);}}}};</script>
